using System;
using System.IO;
using System.Text;

namespace Murmur.Next.Probe
{
    /// <summary>
    /// Bounded dependency-free prompt export helper for the Claude Code
    /// external-editor command.
    ///
    /// Copies a temp prompt file (generated by the owned Claude child) to an
    /// export file. Both paths must be absolute and beneath the same allowed
    /// temp directory. The source file is never altered or deleted. File
    /// contents are never logged. No shell execution, no path interpolation.
    ///
    /// Returns 0 on success, nonzero on failure. Failure reasons are status
    /// codes only and never include transcript or file contents.
    /// </summary>
    public static class PromptExport
    {
        /// <summary>Maximum accepted input size: 1 MiB.</summary>
        public const long MaxInputBytes = 1048576L;

        private static readonly Encoding StrictUtf8 = new UTF8Encoding(false, true);

        /// <summary>
        /// Export the prompt file at <paramref name="inputFile"/> to
        /// <paramref name="exportFile"/>. Both must live beneath
        /// <paramref name="allowedTempDirectory"/>.
        /// </summary>
        /// <returns>0 on success, nonzero on failure.</returns>
        public static int Run(string inputFile, string allowedTempDirectory, string exportFile)
        {
            if (string.IsNullOrWhiteSpace(inputFile)) return 1;
            if (string.IsNullOrWhiteSpace(allowedTempDirectory)) return 1;
            if (string.IsNullOrWhiteSpace(exportFile)) return 1;

            if (!Path.IsPathRooted(inputFile)) return 2;
            if (!Path.IsPathRooted(allowedTempDirectory)) return 2;
            if (!Path.IsPathRooted(exportFile)) return 2;

            string rootFull;
            string inputFull;
            string exportFull;
            try
            {
                rootFull = Path.GetFullPath(allowedTempDirectory);
            }
            catch
            {
                return 3;
            }
            try
            {
                inputFull = Path.GetFullPath(inputFile);
            }
            catch
            {
                return 3;
            }
            try
            {
                exportFull = Path.GetFullPath(exportFile);
            }
            catch
            {
                return 3;
            }

            if (!Directory.Exists(rootFull)) return 4;

            char[] separators = new char[] { Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar };
            string rootTrimmed = rootFull.TrimEnd(separators);
            if (rootTrimmed.Length == 0) return 4;
            string rootWithSeparator = rootTrimmed + Path.DirectorySeparatorChar;

            if (!IsWithinRoot(inputFull, rootWithSeparator)) return 5;
            if (!IsWithinRoot(exportFull, rootWithSeparator)) return 5;

            if (string.Equals(inputFull, exportFull, StringComparison.OrdinalIgnoreCase)) return 6;

            string exportParent;
            try
            {
                exportParent = Path.GetDirectoryName(exportFull);
            }
            catch
            {
                return 7;
            }
            if (string.IsNullOrEmpty(exportParent)) return 7;

            if (ContainsReparsePoint(inputFull, rootTrimmed)) return 8;
            if (ContainsReparsePoint(exportParent, rootTrimmed)) return 8;
            if ((File.Exists(exportFull) || Directory.Exists(exportFull)) && IsReparsePoint(exportFull)) return 8;

            if (File.Exists(exportFull) || Directory.Exists(exportFull)) return 9;
            if (!Directory.Exists(exportParent)) return 10;
            if (!File.Exists(inputFull)) return 10;

            byte[] bytes;
            try
            {
                using (FileStream source = new FileStream(inputFull, FileMode.Open, FileAccess.Read, FileShare.Read))
                {
                    if (source.Length > MaxInputBytes) return 11;
                    bytes = new byte[(int)source.Length];
                    int offset = 0;
                    while (offset < bytes.Length)
                    {
                        int count = source.Read(bytes, offset, bytes.Length - offset);
                        if (count == 0) return 11;
                        offset += count;
                    }
                    if (source.ReadByte() != -1) return 11;
                }
            }
            catch
            {
                return 11;
            }
            if (bytes.Length > MaxInputBytes) return 11;

            try
            {
                if (bytes.Length > 0)
                {
                    StrictUtf8.GetString(bytes);
                }
            }
            catch (DecoderFallbackException)
            {
                return 12;
            }
            catch (ArgumentException)
            {
                return 12;
            }
            catch
            {
                return 12;
            }

            string staging = null;
            bool staged = false;
            try
            {
                staging = Path.Combine(
                    exportParent,
                    Path.GetFileName(exportFull) + ".stg-" + Guid.NewGuid().ToString("N") + ".tmp");
                using (FileStream stream = new FileStream(staging, FileMode.CreateNew, FileAccess.Write, FileShare.None))
                {
                    staged = true;
                    if (bytes.Length > 0)
                    {
                        stream.Write(bytes, 0, bytes.Length);
                    }
                    stream.Flush();
                }
                File.Move(staging, exportFull);
                staged = false;
            }
            catch (IOException)
            {
                return 13;
            }
            catch (UnauthorizedAccessException)
            {
                return 13;
            }
            catch
            {
                return 13;
            }
            finally
            {
                if (staged && staging != null)
                {
                    try
                    {
                        File.Delete(staging);
                    }
                    catch
                    {
                    }
                }
            }

            return 0;
        }

        /// <summary>
        /// Pure validated helper: true when the candidate full path lies
        /// strictly beneath the root. The root must be a full path ending
        /// with a directory separator, which enforces the separator
        /// boundary (a sibling sharing a string prefix does not match).
        /// Comparison is case insensitive. No I/O is performed.
        /// </summary>
        public static bool IsWithinRoot(string candidateFullPath, string rootWithSeparator)
        {
            if (string.IsNullOrEmpty(candidateFullPath)) return false;
            if (string.IsNullOrEmpty(rootWithSeparator)) return false;
            return candidateFullPath.StartsWith(rootWithSeparator, StringComparison.OrdinalIgnoreCase);
        }

        private static bool ContainsReparsePoint(string targetFullPath, string rootTrimmed)
        {
            if (string.IsNullOrEmpty(targetFullPath)) return true;
            if (string.IsNullOrEmpty(rootTrimmed)) return true;

            char[] separators = new char[] { Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar };
            string current = targetFullPath.TrimEnd(separators);
            if (current.Length == 0) return true;

            while (true)
            {
                if (!IsWithinOrEqual(current, rootTrimmed)) break;

                bool exists;
                try
                {
                    exists = File.Exists(current) || Directory.Exists(current);
                }
                catch
                {
                    return true;
                }
                if (exists && IsReparsePoint(current)) return true;

                if (string.Equals(current, rootTrimmed, StringComparison.OrdinalIgnoreCase)) break;

                string parent;
                try
                {
                    parent = Path.GetDirectoryName(current);
                }
                catch
                {
                    return true;
                }
                if (parent == null) break;
                parent = parent.TrimEnd(separators);
                if (parent.Length == 0) break;
                if (parent.Length >= current.Length) break;
                current = parent;
            }

            return false;
        }

        private static bool IsWithinOrEqual(string candidateTrimmed, string rootTrimmed)
        {
            if (string.Equals(candidateTrimmed, rootTrimmed, StringComparison.OrdinalIgnoreCase)) return true;
            return candidateTrimmed.StartsWith(
                rootTrimmed + Path.DirectorySeparatorChar,
                StringComparison.OrdinalIgnoreCase);
        }

        private static bool IsReparsePoint(string path)
        {
            FileAttributes attributes;
            try
            {
                attributes = File.GetAttributes(path);
            }
            catch
            {
                return true;
            }
            return (attributes & FileAttributes.ReparsePoint) == FileAttributes.ReparsePoint;
        }
    }
}
